SELECT id 
FROM w 
WHERE c4 LIKE '%vic grassi%';

SELECT id 
FROM w 
WHERE c4_month = 2;

SELECT id 
FROM w 
WHERE c10_number > 25;

SELECT COUNT(*)
FROM w 
JOIN t_c4_address ON w.c4 = t_c4_address.c4_address;

SELECT COUNT(*) 
FROM w 
WHERE c2 = 'tiger woods';

SELECT COUNT(*) 
FROM w 
WHERE c1 = 'conservative';
